style.css:
@-moz-document domain("roblox.com") {
/* Apply background to HTML and BODY */
    html, body {
        height: 100% !important;
        background: transparent !important;
        color: #e0e0e0 !important;
    }

    /* Apply background to Roblox's main app container */
    #app, .rbx-body, .rbx-content {
        background: url("https://i.pinimg.com/originals/e9/06/67/e906672b7091e259d638b588bccf7e75.jpg") no-repeat center center fixed !important;
        background-size: cover !important;
        min-height: 100vh !important;
    }

    /* Make all other containers transparent */
    div, section, main, header, footer, nav, article {
        background-color: transparent !important;
        background-image: none !important;
    }

    /* Navigation bar */
    .navbar, .nav-container {
        background-color: rgba(0, 0, 0, 0.85) !important;
    }

    /* Links */
    a {
        color: #4da3ff !important;
    }
    a:hover {
        color: #82c7ff !important;
    }

    /* Buttons */
    button, .btn-primary {
        background-color: rgba(0, 0, 0, 0.7) !important;
        color: #ffffff !important;
        border: 1px solid #444 !important;
    }
    button:hover, .btn-primary:hover {
        background-color: rgba(50, 50, 50, 0.8) !important;
    }
}
